rss.channel:
{{ .Site.Title }}
{{ .Permalink }}
{{ .Site.Params.description }}
Hugo
{{ .Site.Language.Locale | default "es-mx" }}
{{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}

{{- $posts := where .Site.RegularPages "Type" "posts" }}
{{- $posts = sort $posts "Date" "desc" }}
{{- range first 20 $posts }}
{{- $unlockDate := "" }}
{{- with .Params.unlock_date }}{{ $unlockDate = time.AsTime . }}{{ end }}
{{- $isLocked := and $unlockDate (gt $unlockDate now) }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
  {{ .Permalink }}
  {{ if $isLocked }}🔒 Próximamente. Se desbloquea el {{ $unlockDate.Format "2 January 2006" }}.{{ else }}{{ .Params.excerpt | default .Summary | plainify }}{{ end }}

{{- end }}
